SELECT count(*), count(c2), sum(c2), total(c2), avg(c2), min(c2), max(c2), count(DISTINCT c2) FROM t1;
SELECT c2, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY c2 ORDER BY c2;
SELECT count(*), count(c2), sum(c2), total(c2), avg(c2), min(c2), max(c2), count(DISTINCT c2) FROM t0 WHERE CAST(id BETWEEN c0 AND 'rho' AS NUMERIC);
SELECT c2, count(*), group_concat(id, ';') FROM (SELECT * FROM t0 ORDER BY id) GROUP BY c2 ORDER BY c2;
SELECT count(*), count(c4), sum(c4), total(c4), avg(c4), min(c4), max(c4), count(DISTINCT c4) FROM t1 WHERE c3;
SELECT c4, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY c4 ORDER BY c4;
SELECT count(*), count(c3), sum(c3), total(c3), avg(c3), min(c3), max(c3), count(DISTINCT c3) FROM t1 WHERE c0 BETWEEN CASE WHEN c0 THEN 9223372036854775807 ELSE -859 END AND NULL BETWEEN id AND NULL;
SELECT c3, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY c3 HAVING count(*) > 1 ORDER BY c3;
SELECT count(*), count(c2), sum(c2), total(c2), avg(c2), min(c2), max(c2), count(DISTINCT c2) FROM t1;
SELECT c2, count(*), group_concat(id) FROM (SELECT * FROM t1 ORDER BY id) GROUP BY c2 ORDER BY c2;
SELECT count(*), count(c1), sum(c1), total(c1), avg(c1), min(c1), max(c1), count(DISTINCT c1) FROM t0;
SELECT c1, count(*), group_concat(id, ';') FROM (SELECT * FROM t0 ORDER BY id) GROUP BY c1 ORDER BY c1;
SELECT a.id, b.id, a.c2, b.ref FROM t0 a LEFT JOIN t1 b ON b.ref = a.id ORDER BY 1, 2 LIMIT 11;
SELECT count(*) FROM t0 a JOIN t0 b USING(id) WHERE a.x'52fda434c3';
SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', 4, 3), instr('0x1F', 'über'), replace('0x1F', 'é', '_'), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE '%é%', '0x1F' GLOB '*', char(85, 980), '0x1F' || 'über', '0x1F' < 'über', '0x1F' = 'über' COLLATE NOCASE;
